const assert=require('node:assert/strict'),E=require('./engine.js');let n=0;
const test=(name,f)=>{f();n++;console.log('PASS '+name)};
function empty(){let s=E.demo();s.grant.start='2026-01';s.grant.end='2026-12';s.grant.asOf='2026-01';s.people=[];s.ledger=[];s.supplies=[];s.costs=[];s.subawards=[];s.subPays=[];s.planned={};s.assume={Travel:0,Other:0};return s}
test('Future actuals excluded',()=>{let s=empty();s.ledger=[{cat:'Travel',month:'2026-12',amount:1200}];assert.equal(E.calculate(s).total.actual,0)});
test('Six month budget retained',()=>{let s=empty();s.grant.end='2026-06';s.planned.Travel=[60000];assert.equal(E.calculate(s).direct.plan,60000)});
test('First eligible subaward payment consumes base first',()=>{let s=empty();s.subawards=[{id:1,name:'Test',start:'2026-01',end:'2026-12',total:100000,subj:50000}];s.subPays=[{sub:1,month:'2026-01',amount:20000}];assert.equal(E.calculate(s).idc.actual,9800);assert.equal(E.calculate(s).idc.proj,24500)});
test('Before-start elapsed zero and null pace',()=>{let s=empty();s.grant.asOf='2025-12';let c=E.calculate(s);assert.equal(c.elapsed,0);assert.equal(c.burn,null)});
test('After-end future forecast absent',()=>{let s=empty();s.grant.asOf='2027-01';assert.equal(E.calculate(s).left,0)});
test('Proposal ignores posted actuals',()=>{let s=empty();s.grant.mode='proposal';s.ledger=[{cat:'Travel',month:'2026-01',amount:1200}];assert.equal(E.calculate(s).total.actual,0)});
test('Zero effort differs from blank',()=>{let s=empty(),p={salary:120000,effort:50,fringe:0,eff:{'2026-01':0}};assert.equal(E.person(s,p,'2026-01').cost,0);assert.equal(E.person(s,p,'2026-02').cost,5000)});
test('Year flags and assignment dates',()=>{let s=E.demo(),p=s.people[0];p.years=[false,true];assert.equal(E.person(s,p,'2026-12').cost,0);p.start='2027-02';assert.equal(E.person(s,p,'2027-01').cost,0)});
test('Salary cap preserves actual salary and calculates fringe',()=>{let s=empty(),p={salary:300000,effort:100,fringe:35.4};assert.deepEqual(E.person(s,p,'2026-01'),{salary:25000,charged:19000,excess:6000,fringe:6726,cost:25726,effort:100});assert.equal(p.salary,300000)});
test('Raise effective month',()=>{let s=empty();s.grant.salaryCap=0;let p={salary:120000,effort:100,fringe:0,raiseDate:'2026-06',raisePct:10};assert.equal(E.person(s,p,'2026-05').cost,10000);assert.equal(E.person(s,p,'2026-06').cost,11000)});
test('Posted F&A replaces estimate',()=>{let s=empty();s.ledger=[{cat:'Travel',month:'2026-01',amount:1000}];s.postedFa={'2026-01':450};assert.equal(E.calculate(s).idc.actual,450)});
test('MTDC equipment exclusion and TDC inclusion',()=>{let s=empty();s.ledger=[{cat:'Equipment',month:'2026-01',amount:10000}];assert.equal(E.calculate(s).idc.actual,0);s.grant.base='TDC';assert.equal(E.calculate(s).idc.actual,4900)});
test('Subaward credits restore cap eligibility',()=>{let s=empty();s.grant.asOf='2026-02';s.subawards=[{id:1,name:'Test',start:'2026-01',end:'2026-12',total:100000,subj:50000}];s.subPays=[{sub:1,month:'2026-01',amount:60000},{sub:1,month:'2026-02',amount:-20000}];assert.equal(E.calculate(s).idc.actual,19600)});
test('Scenario cost and quantity compound',()=>{let s=empty();s.supplies=[{month:'2026-02',qty:10,unit:100}];s.scenario={qty:20,cost:10};assert.equal(E.calculate(s).proj.Supplies['2026-02'],1320)});
test('Negative credit allowed and future dates quarantined',()=>{let s=empty();s.ledger=[{cat:'Travel',month:'2026-01',amount:-20},{cat:'Travel',month:'2027-01',amount:9999}];assert.equal(E.calculate(s).direct.actual,-20);assert(E.validate(s).some(x=>x.message.includes('outside')))});
test('Duplicate source IDs rejected',()=>{let s=empty();s.ledger=[1,2].map(id=>({id,cat:'Other',month:'2026-01',amount:20,reference:'same'}));assert(E.validate(s).some(x=>x.level==='error'))});
test('Malformed project rejected',()=>assert.equal(E.validate({})[0].level,'error'));
test('Invalid month and effort rejected',()=>{let s=E.demo();s.people[0].effort=110;assert(E.validate(s).some(x=>x.level==='error'));s.grant.asOf='2026-13';assert.equal(E.validate(s)[0].level,'error')});
test('Cent allocation exact including credits',()=>{for(const x of [100,-100,0.01,-0.01,123.47])assert.equal(E.spread(x,36).reduce((a,b)=>a+E.cents(b),0),E.cents(x))});
test('Summary and chart agree to cent',()=>{let c=E.calculate(E.demo());assert.equal(c.curve.projected.at(-1),c.total.proj);assert.equal(c.curve.plan.at(-1),c.total.plan);assert.equal(c.curve.actual.filter(x=>x!==null).at(-1),c.total.actual)});
test('Repeat computation does not mutate project',()=>{let s=E.demo(),j=JSON.stringify(s);assert.deepEqual(E.calculate(s),E.calculate(s));assert.equal(JSON.stringify(s),j)});
test('60 months 100 staff 20k ledger rows completes under two seconds',()=>{let s=E.demo();s.grant.end='2030-12';s.people=Array.from({length:100},(_,i)=>({...s.people[1],id:'p'+i}));s.ledger=Array.from({length:20000},(_,i)=>({id:i,cat:'Other',month:'2026-01',amount:1,reference:'r'+i}));let t=performance.now();let c=E.calculate(s);assert.equal(c.months.length,60);assert(performance.now()-t<2000)});
test('Unknown category and unsafe identifiers rejected',()=>{let s=empty();s.ledger=[{id:'<bad>',cat:'<img>',month:'2026-01',amount:20}];assert(E.validate(s).filter(x=>x.level==='error').length>=2)});
test('Subaward nonnumeric base rejected',()=>{let s=empty();s.subawards=[{id:1,start:'2026-01',end:'2026-12',total:100,subj:'bad'}];assert(E.validate(s).some(x=>x.level==='error'))});
test('Overdue subaward retains unpaid forecast balance',()=>{let s=empty();s.grant.asOf='2026-06';s.subawards=[{id:1,name:'Overdue',start:'2026-01',end:'2026-03',total:1000,subj:1000}];assert.equal(E.calculate(s).proj[E.SUB]['2026-07'],1000)});
console.log(n+' tests passed');
